package dev.cdelmonte.collecting.distribution;

import dev.cdelmonte.collecting.musicalwork.ExploitationType;

import java.util.Map;

/**
 * Regulatory rate category from the GEMA tariff structure (Tarifordnung).
 * Each exploitation type is assigned a tariff class that determines the
 * royalty rate applied to the revenue generated by that type of usage.
 *
 * Encapsulates the mapping from {@link ExploitationType} to a decimal rate,
 * replacing the switch statement that previously lived in DistributionService.
 */
public final class TariffClass {

    private static final Map<ExploitationType, Double> RATES = Map.of(
            ExploitationType.BROADCAST,               0.09,
            ExploitationType.PUBLIC_PERFORMANCE,      0.12,
            ExploitationType.MECHANICAL_REPRODUCTION, 0.065,
            ExploitationType.DIGITAL_STREAMING,       0.04,
            ExploitationType.SYNCHRONIZATION,         0.05
    );

    private final ExploitationType exploitationType;
    private final double rate;

    private TariffClass(ExploitationType exploitationType, double rate) {
        this.exploitationType = exploitationType;
        this.rate = rate;
    }

    /**
     * Returns the TariffClass for the given exploitation type.
     *
     * @throws IllegalArgumentException if the exploitation type has no registered tariff
     */
    public static TariffClass forExploitationType(ExploitationType exploitationType) {
        Double rate = RATES.get(exploitationType);
        if (rate == null) {
            throw new IllegalArgumentException(
                    "No tariff rate defined for exploitation type: " + exploitationType);
        }
        return new TariffClass(exploitationType, rate);
    }

    /** Returns the decimal royalty rate for this tariff class (e.g. 0.09 = 9%). */
    public double rate() { return rate; }

    public ExploitationType getExploitationType() { return exploitationType; }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof TariffClass)) return false;
        TariffClass that = (TariffClass) o;
        return exploitationType == that.exploitationType;
    }

    @Override
    public int hashCode() {
        return exploitationType.hashCode();
    }

    @Override
    public String toString() {
        return "TariffClass[" + exploitationType + ", rate=" + rate + "]";
    }
}
